function UIMainInteractionFeelingDialog:PlayBeginTimeLine()
    local id = PhoneUtils.GetOrderTLId(self._curRoleId, 1)
    local vo = PhoneUtils.GetOrderTimeLineConfigVo(id)
    if not vo then
        return
    end
    if CfUtils.IsWoman() then
        CriWareUtils.PlayVoiceById(vo.voicecodeLady, self._roleGo)
    else
        CriWareUtils.PlayVoiceById(vo.voicecode, self._roleGo)
    end
    CfUtils.FillText(self.TextContent, CfUtils.GetSexDesc(vo.desc, self._curRoleId))

    self._tlBeginLoader = ResourceModule.LoadBundleSync(vo.prefab)
    if self._tlBeginLoader.IsSuccess then
        self._tlBeginGo = CfUtils.InstantiateGo(self._tlBeginLoader.ResultObject.gameObject, self._parGo.transform:Find("RolePar/"..self._curRoleId))
        local pd = KTool.GetComponent(self._tlBeginGo, typeof(CS.UnityEngine.Playables.PlayableDirector))
        if pd then
            KTool.SetActive(self._tlBeginGo, true)
            pd:Pause()
            pd.time = 0

            local bindList = support.new_list(typeof(CS.UnityEngine.Playables.PlayableBinding))
            bindList:AddRange(pd.playableAsset.outputs)
            for i = 0, bindList.Count - 1 do
                local bind = bindList[i]
                --只设置人的节点
                if bind.streamName == "role" then
                    pd:SetGenericBinding(bind.sourceObject, self._roleGo)
                elseif bind.streamName == "cup" then
                    --pd:SetGenericBinding(bind.sourceObject, self._cupGo)
                end
            end
            self._cupGo.transform:SetParent(self._tlBeginGo.transform:Find("home_f_2_cup/locator1").transform)
            pd:Play()
            coroutine.yield(WaitForSeconds(pd.duration))
            KTool.SetActive(self._tlBeginGo, false)
            self._cupGo.transform:SetParent(self._cupParGo.transform)

            self:PlayRoleTalk()
        end
    end
end

