function UIMainInteractionFeelingDialog:OnSwipeActionEvent(gesture)
    if self._isEnd then
        return
    end
    if gesture then
        if isNull(gesture.pickedObject) then
            return
        else
            if gesture.pickedObject.name ~= self._foodGo.name then
                return
            end
        end

        if gesture.type == EasyTouch.EvtType.On_SwipeStart then    
            self._dragTime = 0
            self._isDrag = true
            self._foodGo.transform.localPosition = Vector3(0, 0, 0)
            CfUtils.SetActive(self._foodGo.transform:Find("shadow"), false)
        elseif gesture.type == EasyTouch.EvtType.On_Swipe then
            local position3D = self._mainCam.transform:InverseTransformPoint(self._foodGo.transform.position)
            local pos = self._mainCam:ScreenToWorldPoint(Vector3(gesture.position.x, gesture.position.y, position3D.z))
            self._foodGo.transform.position = pos
            pos = self._foodGo.transform.localPosition
            if checkNumber(pos.y) < 0 then
                pos = Vector3(0, 0, pos.z)
            end
            self._foodGo.transform.localPosition = pos
        elseif gesture.type == EasyTouch.EvtType.On_SwipeEnd then
            self._lookAtController.enabled = false
            self._lookAtIk.enabled = false
            CfUtils.SetActive(self._foodGo.transform:Find("shadow"), true)

            self._foodGo.transform.localPosition = Vector3(0, 0, 0)
            self._isDrag = false
            self._dragTime = 0
            self._roleAni:SetInteger("play", 0)
            self._roleAni:SetInteger("emoji", 0)
            self._curDragType = 0
            KTool.SetActive(self.DialogueFrameNode, false)
        end
    end
end

function UIMainInteractionFeelingDialog:SetRoleClick(go, type)
    if isNull(go) then
        return
    end

    local quickTap = KTool.GetOrAddComponent(go.gameObject, typeof(CS.HedgehogTeam.EasyTouch.QuickTap))
