function UIMainInteractionFeelingDialog:GetLoader(path)
    path = checkString(path)
    --创建
    if isNull(RolesShowMgr:GetInstance():GetCoffeeLoader(path)) then
        local roleLoader = ResourceModule.LoadBundleSync(path, nil, true)
        if roleLoader.IsSuccess then
            RolesShowMgr:GetInstance():PushCoffeeLoader(roleLoader, path)
        else
            roleLoader:Release()
            return nil
        end
        return roleLoader
    end
    return RolesShowMgr:GetInstance():GetCoffeeLoader(path)
end

--刷新特效
function UIMainInteractionFeelingDialog:RefreshEffectGo(name)
    name = checkString(name)
    local path = "Effect/prefab/coffee/"..name..".prefab"

    if not isNull(self._effectGo) then
        GameObject.Destroy(self._effectGo)
    end
    self._effectGo = nil

    if string.isEmpty(name) then
        return
    end
    local loader = self:GetLoader(path)
    local go = GameObject.Instantiate(loader.ResultObject)
    if not isNull(go) then
        go.transform.parent = self._parGo.transform:Find("RolePar/"..self._curRoleId)
        self._effectGo = go
        self._effectGo.transform.localPosition = Vector3(0, 0, 0)
        self._effectGo.transform.localRotation = Quaternion.Euler(0, 0, 0)
        self._effectGo.transform.localScale = Vector3(1, 1, 1)
    end
end

function UIMainInteractionFeelingDialog:PlayEndTimeLine()
    local id = PhoneUtils.GetOrderTLId(self._curRoleId, 2)
    local vo = PhoneUtils.GetOrderTimeLineConfigVo(id)
    if not vo then
        return
    end

    if CfUtils.IsWoman() then
        CriWareUtils.PlayVoiceById(vo.voicecodeLady, self._roleGo)
    else
        CriWareUtils.PlayVoiceById(vo.voicecode, self._roleGo)
    end

    KTool.SetActive(self.DialogueFrameNode, true)
    
    CfUtils.FillText(self.TextContent, CfUtils.GetSexDesc(vo.desc, self._curRoleId))

    self._tlEndLoader = ResourceModule.LoadBundleSync(vo.prefab)
    if self._tlEndLoader.IsSuccess then
        self._tlEndGo = CfUtils.InstantiateGo(self._tlEndLoader.ResultObject.gameObject, self._parGo.transform:Find("RolePar/"..self._curRoleId))
        local pd = KTool.GetComponent(self._tlEndGo, typeof(CS.UnityEngine.Playables.PlayableDirector))
        if pd then
            KTool.SetActive(self._tlEndGo, true)
            pd:Pause()
            pd.time = 0

            local bindList = support.new_list(typeof(CS.UnityEngine.Playables.PlayableBinding))
            bindList:AddRange(pd.playableAsset.outputs)
            for i = 0, bindList.Count - 1 do
                local bind = bindList[i]
                --只设置人的节点
                if bind.streamName == "role" then
                    pd:SetGenericBinding(bind.sourceObject, self._roleGo)
                --elseif bind.streamName == "cup" then
                    --pd:SetGenericBinding(bind.sourceObject, self._cupGo)
                end
            end
            self._cupGo.transform:SetParent(self._tlEndGo.transform:Find("home_f_2_cup/locator1").transform)

            pd:Play()
            coroutine.yield(WaitForSeconds(pd.duration))
            GameObject.Destroy(self._tlEndGo)
            KTool.SetActive(self._tlEndGo, false)
            self._cupGo.transform:SetParent(self._cupParGo.transform)

            self:OnFinish()
        end
    end
end

function UIMainInteractionFeelingDialog:InitData()
    local isDrinkLike = PhoneUtils.IsRoleLikeFood(self._curRoleId, self._curDrinkId)
    local isFoodLike = PhoneUtils.IsRoleLikeFood(self._curRoleId, self._curFoodId)
    local t = {}
    --触发特殊剧情
    if isDrinkLike and isFoodLike then
        t = PhoneUtils.GetRoleSpecialStoryIds(self._curRoleId, self._curDrinkId, self._curFoodId)
        self._isSpecial = true
    else
        t = PhoneUtils.GetRoleCommonStoryIds(self._curRoleId)
        self._isSpecial = false
    end
    local ind = math.random(table.count(t))
    self._curStoryId = t[ind]
    if self._isSpecial then
        self._allStoryIds = PhoneUtils.GetRoleSpecialStoryCfIds(self._curStoryId)
    else
        self._allStoryIds = PhoneUtils.GetRoleCommonStoryCfIds(self._curStoryId)
    end
end

function UIMainInteractionFeelingDialog:FillSelf()
    local name = PhoneUtils.GetRoleCurName(self._curRoleId)
    CfUtils.FillText(self.TxtLeftName, name)
    CfUtils.SetActive(self.DialogueFrameNode.transform:Find("DialogFrame/Layout/FrameGroup/Titles"), true)
    self:InitSceneModle()
end

--绘制喝咖啡场景的模型
function UIMainInteractionFeelingDialog:InitSceneModle()
    --杯子合盘子
    local vo = PhoneUtils.GetPhoneRoleVisitingVo(self._curRoleId)
    if vo then
        self._cupLoader = ResourceModule.LoadBundleSync(vo.cup, nil, true)
        if self._cupLoader.IsSuccess then
            self._cupGo = CfUtils.InstantiateGo(self._cupLoader.ResultObject, self._cupParGo)
        else
            self._cupLoader:Release()
        end

        self._plateLoader = ResourceModule.LoadBundleSync(vo.plate, nil, true)
        if self._plateLoader.IsSuccess then
            self._plateGo = CfUtils.InstantiateGo(self._plateLoader.ResultObject, self._parGo.transform:Find("PlatePar"))
        else
            self._plateLoader:Release()
        end
    end

    vo = CookingUtils.GetOrderFoodVo(self._curDrinkId)
    if vo and not string.isEmpty(vo.model) then
        self._drinkLoader = ResourceModule.LoadBundleSync(vo.model, nil, true)
        if self._drinkLoader.IsSuccess then
            self._drinkGo = CfUtils.InstantiateGo(self._drinkLoader.ResultObject, self._parGo.transform:Find("DrinkPar"))
        else
            self._drinkLoader:Release()
        end

        if not isNull(self._drinkGo) then
            KTool.SetActive(self._drinkGo, true)
        end
        self._drinkGo.transform.localPosition = Vector3(0, 0, 0)
    end

    vo = CookingUtils.GetOrderFoodVo(self._curFoodId)
    if vo and not string.isEmpty(vo.model) then
        self._foodLoader = ResourceModule.LoadBundleSync(vo.model, nil, true)
        if self._foodLoader.IsSuccess then
            self._foodGo = CfUtils.InstantiateGo(self._foodLoader.ResultObject, self._parGo.transform:Find("FoodPar"))
        else
            self._foodLoader:Release()
        end
        if not isNull(self._drinkGo) then
            KTool.SetActive(self._drinkGo, true)
        end
        self._foodGo.transform.localPosition = Vector3(0, 0, 0)
    end
end

function UIMainInteractionFeelingDialog:OnUpdate()
    --[[
    --不在播放中
    if not self._playing then
        return
    end

    self._playTime = self._playTime + CS.UnityEngine.Time.deltaTime
    if self._playTime >= self._waitTime then
        self._playTime = 0
        self:RefreshTalk()
    end
    ]]

    if self._isDrag then
        self._dragTime = self._dragTime + CS.UnityEngine.Time.deltaTime
        self:CheckDrag()
    end

    if checkNumber(self._talkTime) > 0 then
        self._talkTime = self._talkTime - CS.UnityEngine.Time.deltaTime

        if checkNumber(self._talkTime) <= 0 then
            self._talkTime = 0 
            self._roleAni:SetInteger("talk", 0)
            self._roleAni:SetInteger("emoji", 0)
        end
    end 
    --[[
    if self._isTalk then
        local animatorInfo = self._roleAni:GetCurrentAnimatorStateInfo(0)
        if isNull(animatorInfo) then
            return
        end
        if not animatorInfo:IsName("home_f_initial") then 
            self._roleAni:SetInteger("talk", 0)
            self._roleAni:SetInteger("emoji", 0)
        end
    end
    ]]

    if self._isTouch then
        local animatorInfo = self._roleAni:GetCurrentAnimatorStateInfo(0)
        if isNull(animatorInfo) then
            return
        end
        if not animatorInfo:IsName("home_f_initial") then 
            self._roleAni:SetInteger("touch", 0)
            self._roleAni:SetInteger("emoji", 0)
            self._isTouch = false
            self._isBeginAni = true
        end
    end

    if self._isBeginAni then
        local animatorInfo = self._roleAni:GetCurrentAnimatorStateInfo(0)
        if not isNull(animatorInfo) then
            if animatorInfo:IsName("home_f_initial") then 
                KTool.SetActive(self.DialogueFrameNode, false)
                self._isBeginAni = false
            end
        end
    end
end

function UIMainInteractionFeelingDialog:CheckDrag()
    if #self._allDragTalkVo > #DragInfo then
        return
    end 

    for i = #self._allDragTalkVo, 1, -1 do
        local data = DragInfo[i]
        if self._dragTime >= data.time then
            self:HandleDrag(self._allDragTalkVo[i])
            return
        end
    end
end

function UIMainInteractionFeelingDialog:HandleDrag(vo)
    if not vo then
        return
    end
    if checkNumber(vo.action) == checkNumber(self._curDragType) then
        return
    end
    self._curDragType = checkNumber(vo.action)
    --[[
    local vo = PhoneUtils.GetRandomDragTalkVo(self._curRoleId, type)
    if not vo then
        return
    end
    ]]
    if checkNumber(vo.eye) == 1 then
        self._lookAtController.enabled = true
        self._lookAtIk.enabled = true
    else
        self._lookAtController.enabled = false
        self._lookAtIk.enabled = false
    end

    if CfUtils.IsWoman() then
        CriWareUtils.PlayVoiceById(vo.voicecodeLady, self._roleGo)
    else
        CriWareUtils.PlayVoiceById(vo.voicecode, self._roleGo)
    end

    CfUtils.FillText(self.TextContent, CfUtils.GetSexDesc(vo.text, self._curRoleId))
    self:RefreshEffectGo(vo.specialEffects)

    KTool.SetActive(self.DialogueFrameNode, not string.isEmpty(vo.text))
    self._roleAni:SetInteger("play", vo.action)
    self._roleAni:SetInteger("emoji", vo.faceId)
end

function UIMainInteractionFeelingDialog:RefreshTalk()
    if checkNumber(self._curCfId) == 0 then
        if self._isSpecial then    
            self._curCfId = PhoneUtils.GetRoleSpecialStoryCfId(self._curStoryId, 1)
        else    
            self._curCfId = PhoneUtils.GetRoleCommonStoryCfId(self._curStoryId, 1)
        end
    end

    self:RefreshCurInfo()
end

--刷新当前信息
function UIMainInteractionFeelingDialog:RefreshCurInfo()
    if checkNumber(self._curCfId) == 0 then
        return
    end

    local storyId = self._curCfId
    local storyVo = PhoneUtils.GetRoleStoryCfVo(storyId, self._isSpecial)
    if not storyVo then
        return
    end

    if CfUtils.IsWoman() then
        CriWareUtils.PlayVoiceById(storyVo.voiceLady, self._roleGo)
    else
        CriWareUtils.PlayVoiceById(storyVo.voice, self._roleGo)
    end

    CriWareUtils.PlaySeById(storyVo.sound)
    CriWareUtils.PlayMusicById(storyVo.music)

    CfUtils.FillText(self.TextContent, CfUtils.GetSexDesc(storyVo.desc, self._curRoleId))

    --[[
    if checkNumber(storyVo.people) == 1 then
        local name = PhoneUtils.GetRoleCurName(self._curRoleId)
        CfUtils.FillText(self.TxtLeftName, name)
    else
        CfUtils.FillText(self.TxtLeftName, "")
    end
    ]]
    CfUtils.FillText(self.TxtLeftName, storyVo.name)

    local actNum = checkNumber(storyVo.action)
    if actNum > 0 then
        self._roleAni:SetInteger("talk", actNum)
        self._roleAni:SetInteger("emoji", storyVo.faceId)
    end
    
    --只有上一个动作播完才重新给他赋值
    if checkNumber(self._talkTime) <= 0 then
        self._talkTime = checkNumber(storyVo.time)
    end

    --有选项
    if checkNumber(storyVo.choiceOneId) > 0 then
        --self._playing = false
        self:FillOptionss(storyVo)
        return
    --结束了
    elseif checkNumber(storyVo.isEnd) == 1 then
        --self._playing = false
        --self:OnFinish()
        self._isStoryFinish = true
        return
    end

    if self._isSpecial then    
        self._curCfId = PhoneUtils.GetRoleSpecialStoryCfId(self._curStoryId, storyVo.jumpId)
    else    
        self._curCfId = PhoneUtils.GetRoleCommonStoryCfId(self._curStoryId, storyVo.jumpId)
    end

    --self._curCfId = PhoneUtils.GetRoleSpecialStoryCfId(self._curStoryId, storyVo.jumpId) --storyVo.jumpId
end

function UIMainInteractionFeelingDialog:FillBar(ind)
    local fillValue = ind/table.count(self._allStoryIds)
    self.ProgressBar.value = fillValue
end

--选项
function UIMainInteractionFeelingDialog:FillOptionss(vo)
    if not vo then
        return
    end
    KTool.SetActive(self.Option, true)
    for i = 1, MaxOptionsNum do
        local go = self.grid.transform:Find("BtnOption"..i)
        local data 
        if i == 1 then
            data = {
                id = vo.choiceOneId,
                desc = vo.choiceOne,
            }
        elseif i == 2 then
            data = {
                id = vo.choiceTwoId,
                desc = vo.choiceTwo,
            }
        elseif i == 3 then
            data = {
                id = vo.choiceThreeId,
                desc = vo.choiceThree,
            }
        end
        self:FillOptions(go, data)
    end
end

function UIMainInteractionFeelingDialog:FillOptions(go, data)
    if not go or not data then
        return
    end
    if checkNumber(data.id) == 0 then
        KTool.SetActive(go, false)
        return
    end
    CfUtils.FillText(go.transform:Find("Text"), data.desc)
    SetButtonAction(go, function()
        self:ChooseOption(data.id)
    end)
    KTool.SetActive(go, true)
end

function UIMainInteractionFeelingDialog:ChooseOption(jumpId)
    if checkNumber(jumpId) == 0 then
        return
    end
    KTool.SetActive(self.Option, false)

    self._curCfId = PhoneUtils.GetRoleSpecialStoryCfId(self._curStoryId, jumpId)
    self._playTime = self._waitTime
    --self._playing = true

    self:RefreshTalk()
end

--结束
function UIMainInteractionFeelingDialog:OnFinish()
    self._isPlayFinishAni = true
    self._finishCo = cs_coroutine.start(function()
        KTool.SetActive(self.BtnSkip, false)
        KTool.SetActive(self.DialogueFrameNode, false)
        KTool.SetActive(self.Option, false)
        KTool.SetActive(self.Feeling, true)
        self.Feeling.gameObject:GetComponent(typeof(UIEffectCapturedImage)):Capture()
        
        local level, exp = PhoneUtils.GetCatFavorabilityLevelAndCurExp(self._curRoleId)
        --level, exp = 1, 20

        local isMaxLevel = PhoneUtils.IsMaxLevel(level)
        CfUtils.FillText(self.TextLevelNumber, self._oldLevel)
        local oldAllExp = PhoneUtils.GetLikabilityLevelUpAllExp(self._oldLevel)
        CfUtils.FillText(self.TextNumberTotal, "<size=36><color=#ffffff>"..self._oldExp.."</color></size>/"..oldAllExp)
        self.ProgressBar.value = self._oldExp/oldAllExp
        
        local num = 2.5
        if self._isSpecial then
            KTool.SetActive(self.SpHeart, true)
        else
            KTool.SetActive(self.NormalHeart, true)
        end
        coroutine.yield(WaitForSeconds((2.5)))
        KTool.SetActive(self.ProgressGroup, true)

        local addExp = PhoneUtils.GetRoleFavorabilityAdd(self._curRoleId, self._curFoodId, self._curDrinkId)
        local targetFillGo 
        if self._isSpecial then
            targetFillGo = self.SPFill
            KTool.SetActive(self.ParticleRoot, true)
        else
            targetFillGo = self.NormalFill
            KTool.SetActive(self.ParticleRoot, false)
        end
        if targetFillGo then
            CfUtils.FillText(targetFillGo.transform:Find("TextUpNumber"), "+0")
            KTool.SetActive(targetFillGo, true)
        end

        coroutine.yield(WaitForSeconds((0.5)))

        local allBuffValue = 0
        local isUpLevel = level > self._oldLevel    
        local oldBufferValue = self._oldLevel    
        --升级
        if isUpLevel then
            for i = self._oldLevel + 1, level do
                oldAllExp = PhoneUtils.GetLikabilityLevelUpAllExp(self._oldLevel)
                local bufferValue

                local orogressBarValue = 0
                --还有一级
                if i == oldBufferValue + 1 then
                    bufferValue = oldAllExp - self._oldExp
                    orogressBarValue = self._oldExp
                else
                    bufferValue = oldAllExp
                    orogressBarValue = 0
                end

                CfUtils.DoTween(1, function(value)
                    local num = checkInt(orogressBarValue + bufferValue * value)
                    self.ProgressBar.value = num/oldAllExp
                    CfUtils.FillText(self.TextNumberTotal, "<size=36><color=#ffffff>"..num.."</color></size>/"..oldAllExp)
    
                    CfUtils.FillText(targetFillGo.transform:Find("TextUpNumber"), "+"..(allBuffValue + checkInt(bufferValue * value)))
                end)
                coroutine.yield(WaitForSeconds((1)))
                allBuffValue = allBuffValue + bufferValue

                CfUtils.PlayAnimator(self.Level, "Play")

                CfUtils.FillText(self.TextLevelNumber, i)

                --[[
                local lastBufferValue = bufferValue
                --还有一级
                if i < level then
                    bufferValue = PhoneUtils.GetLikabilityLevelUpAllExp(i)
                else
                    bufferValue = exp - PhoneUtils.GetLikabilityLevelAllExp(nil, i)
                end
                CfUtils.FillText(self.TextLevelNumber, i)
                local allExp = PhoneUtils.GetLikabilityLevelUpAllExp(i)
                CfUtils.DoTween(1, function(value)
                    local num = checkInt(bufferValue * value)
                    self.ProgressBar.value = num/allExp
                    CfUtils.FillText(self.TextNumberTotal, "<size=36><color=#ffffff>"..num.."</color></size>/"..allExp)
    
                    CfUtils.FillText(targetFillGo.transform:Find("TextUpNumber"), "+"..(lastBufferValue + checkInt(bufferValue * value)))
                end)
                coroutine.yield(WaitForSeconds((1)))
                ]]
                self._oldLevel = i
            end

            local bufferValue = exp
            local allExp = PhoneUtils.GetLikabilityLevelUpAllExp(level)
            CfUtils.DoTween(1, function(value)
                local num = checkInt(bufferValue * value)
                self.ProgressBar.value = num/allExp
                CfUtils.FillText(self.TextNumberTotal, "<size=36><color=#ffffff>"..num.."</color></size>/"..allExp)

                CfUtils.FillText(targetFillGo.transform:Find("TextUpNumber"), "+"..(allBuffValue + checkInt(bufferValue * value)))
            end)
            coroutine.yield(WaitForSeconds((1)))
        else
            local bufferValue = exp - self._oldExp
            CfUtils.DoTween(2, function(value)
                local num = checkInt(self._oldExp + bufferValue * value)
                self.ProgressBar.value = num/oldAllExp
                CfUtils.FillText(self.TextNumberTotal, "<size=36><color=#ffffff>"..num.."</color></size>/"..oldAllExp)

                CfUtils.FillText(targetFillGo.transform:Find("TextUpNumber"), "+"..checkInt(bufferValue * value))
            end)
        end
        CfUtils.PlayAnimator(targetFillGo, "Play")

        if isUpLevel then
            local rewards = PhoneUtils.GetLikabilityRewardDatas(self._curRoleId, level)
            if rewards then
                if rewards.voice == 1 then
                    KTool.SetActive(self.FunctionList.transform:Find("ImgLine1"), true)
                    --[[
                    local go = CfUtils.InstantiateGo(self.TextTitle, self.FunctionList)
                    if go then
                        CfUtils.FillText(go, localize("新语音解锁"))
                    end
                    ]]
                end
                if rewards.news == 1 then
                    KTool.SetActive(self.FunctionList.transform:Find("ImgLine2"), true)
                    --[[
                    KTool.SetActive(self.NewFunctionUnLock, true)
                    local go = CfUtils.InstantiateGo(self.ImgLine, self.FunctionList)
                    local go = CfUtils.InstantiateGo(self.TextTitle, self.FunctionList)
                    if go then
                        CfUtils.FillText(go, localize("新图鉴解锁"))
                    end
                    ]]
                end
            end
        end
        self._isFinish = true
        KTool.SetActive(self.ImgBg, true)
        --[[
        --满级
        if isMaxLevel then
            KTool.SetActive(self.TextTotal2, true)
            KTool.SetActive(self.TextAddNumber, false)
            CfUtils.FillText(self.TextTitle, localize("好感度已满"))
            self.ProgressBar.value = 1
        else
            KTool.SetActive(self.TextTotal, true)
            KTool.SetActive(self.TextAddNumber, true)
            self.ProgressBar.value = exp/PhoneUtils.GetLikabilityLevelUpAllExp(level) 
            --升级
            if level > self._oldLevel then
                KTool.SetActive(self.SPParticleNode, true)
            end

            local addExp = PhoneUtils.GetRoleFavorabilityAdd(self._curRoleId, self._curFoodId, self._curDrinkId)
            local status = 1
            if self._isSpecial then
                CfUtils.FillText(self.TextTitle, localize("特殊好感度UP"))
                status = 2
            else
                CfUtils.FillText(self.TextTitle, localize("好感度UP"))
            end
            CfUtils.SetUISwitchText(self.TextTitle, status)
            CfUtils.FillText(self.TextTotal, exp.."/"..PhoneUtils.GetLikabilityLevelUpAllExp(level))
            CfUtils.FillText(self.TextAddNumber, "+"..addExp)
        end
        ]]

        --coroutine.yield(WaitForSeconds((2)))
        --UIModule.BackDialog()
    end)
end 

function UIMainInteractionFeelingDialog:OnHide()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
    end))
    return coWait
end

function UIMainInteractionFeelingDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("UIMainInteractionOrderPartTL")

        SetButtonAction(self.BtnSkip, function()
            self._isTalk = false
            self._playing = false
            self:OnFinish()
        end)

        SetButtonAction(self.BtnEnd, function()
            cs_coroutine.start(function()
                self._isEnd = true
                KTool.SetActive(self.DateProgressGroup, false)
                self:PlayEndTimeLine()
            end)
        end)
        
        SetButtonAction(self.ImgBg, Bind(self, self.OnClick))
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
        self._behaviourAction.UpdateAction = function()
            self:OnUpdate()
        end
        self._isXiaoBai = (argument.isXiaoBai)
    
        self._curRoleId = checkNumber(argument.roleId)
        self._curDrinkId = checkNumber(argument.drinkId)
        self._curFoodId = checkNumber(argument.foodId)
        self._oldLevel = checkNumber(argument.oldLevel)
        self._oldExp = checkNumber(argument.oldExp)
        self._oldExp = checkNumber(argument.oldExp)

        --self._foodGo = (argument.foodGo)
        --self._drinkGo = (argument.drinkGo)
        self._roleGo = (argument.roleGo)

        if not isNull(self._roleGo) then
            self._roleAni = KTool.GetOrAddComponent(self._roleGo, typeof(Animator))
            self._lookAtController = KTool.GetOrAddComponent(self._roleGo, typeof(CS.RootMotion.FinalIK.LookAtController))
            self._lookAtIk = KTool.GetOrAddComponent(self._roleGo, typeof(CS.RootMotion.FinalIK.LookAtIK))
        end
        self._camName = "Camera_cofa_"..self._curRoleId
        if not isNull(self._parGo) then
            self._cupParGo = self._parGo.transform:Find("CupPar/"..self._curRoleId)
        end
    
        self:InitData()
        self:FillSelf()
    end))
    return coWait
end

function UIMainInteractionFeelingDialog:InitPart3Go()
    CfUtils.SetActive(self.controller.gameObject.transform:Find("Container"), false)
    self._part3Loader = ResourceModule.LoadBundleSync("Timeline/EnterPrefab/Coffee/menu_part03_timeline.prefab", nil, true)
    if self._part3Loader.IsSuccess then
        self._part3Go = CfUtils.InstantiateGo(self._part3Loader.ResultObject, self._parGo)
    else
        self._part3Loader:Release()
    end

    if not isNull(self._part3Go) then
        local pd = KTool.GetComponent(self._part3Go, typeof(CS.UnityEngine.Playables.PlayableDirector))
        if pd then
            KTool.SetActive(self._part3Go, true)
            pd:Pause()
            pd.time = 0

            CfUtils.SetActive(self._foodGo, false)
            CfUtils.SetActive(self._cupGo, false)
            CfUtils.SetActive(self._plateGo, false)

            local bindList = support.new_list(typeof(CS.UnityEngine.Playables.PlayableBinding))
            bindList:AddRange(pd.playableAsset.outputs)
            for i = 0, bindList.Count - 1 do
                local bind = bindList[i]
                --只设置人的节点
                if bind.streamName == "food" then
                    pd:SetGenericBinding(bind.sourceObject, self._foodGo)
                elseif bind.streamName == "cup" then
                    pd:SetGenericBinding(bind.sourceObject, self._cupGo)
                elseif bind.streamName == "plate" then
                    pd:SetGenericBinding(bind.sourceObject, self._plateGo)
                end
            end
            --self._cupGo.transform:SetParent(self._tlBeginGo.transform:Find("home_f_2_cup/locator1").transform)
            pd:Play()
            coroutine.yield(WaitForSeconds(4.6))
            CfUtils.SetActive(self._foodGo, true)
            CfUtils.SetActive(self._cupGo, true)
            CfUtils.SetActive(self._plateGo, true)
            coroutine.yield(WaitForSeconds(pd.duration - 4.6))

            if not isNull(self._part3Go) then
                GameObject.Destroy(self._part3Go)
                self._part3Go = nil
            end
        end
    end

    CfUtils.SetActive(self.controller.gameObject.transform:Find("Container"), true)

    CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIMainInteractionOrderPartTL")
end

function UIMainInteractionFeelingDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self._isBeginAni = false
        self._isTalk = false
        self._isTouch = false
        self._isDrag = false
        if not isNull(self._effectGo) then
            GameObject.Destroy(self._effectGo)
        end

        if not isNull(self._behaviourAction) then
            self._behaviourAction.UpdateAction = nil
        end
        if self._co then
            cs_coroutine.stop(self._co)
            self._co = nil
        end

        RolesShowMgr:GetInstance():ClearCoffeeLoaderAndGo()
        coroutine.yield(RolesShowMgr:GetInstance():SetCameraActivity(false, self._camName, true))

        if not isNull(self._part3Go) then
            GameObject.Destroy(self._part3Go)
        end

        if not isNull(self._cupGo) then
            GameObject.Destroy(self._cupGo)
        end
        if not isNull(self._plateGo) then
            GameObject.Destroy(self._plateGo)
        end

        if not isNull(self._foodGo) then
            GameObject.Destroy(self._foodGo)
        end
        if not isNull(self._drinkGo) then
            GameObject.Destroy(self._drinkGo)
        end

        if not isNull(self._tlBeginGo) then
            GameObject.Destroy(self._tlBeginGo)
        end

        if not isNull(self._tlEndGo) then
            GameObject.Destroy(self._tlEndGo)
        end
        
        if self._part3Loader then
            self._part3Loader:Release(true)
        end

        if self._tlBeginLoader then
            self._tlBeginLoader:Release(true)
        end

        if self._tlEndLoader then
            self._tlEndLoader:Release(true)
        end

        if self._foodLoader then
            self._foodLoader:Release(true)
        end
        if self._drinkLoader then
            self._drinkLoader:Release(true)
        end
        if self._cupLoader then
            self._cupLoader:Release(true)
        end
        if self._plateLoader then
            self._plateLoader:Release(true)
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIMainInteractionFeelingDialog
